using System;using System.IO;using System.Text;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
namespace NeonVault.Editor { public static class ImportedModelProbe {
 public static void Run(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);var log=new StringBuilder();foreach(string name in new[]{"RaiderBossNPC","Enemy_10"}){var obj=UnityEngine.Object.Instantiate(Resources.Load<GameObject>("ImportedEnemies/"+name));var camera=new GameObject("probe").AddComponent<Camera>();camera.orthographic=true;camera.orthographicSize=2;camera.transform.position=new Vector3(0,2,-7);camera.transform.LookAt(Vector3.up);camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.gray;var light=new GameObject("light").AddComponent<Light>();light.type=LightType.Directional;light.transform.rotation=Quaternion.Euler(40,-30,0);foreach(var skin in obj.GetComponentsInChildren<SkinnedMeshRenderer>()){var mesh=new Mesh();skin.BakeMesh(mesh);var b=mesh.bounds;log.AppendLine(name+" / "+skin.name+" vertices="+mesh.vertexCount+" bounds="+b+" world="+skin.transform.position);UnityEngine.Object.DestroyImmediate(mesh);}var rt=new RenderTexture(800,1000,24);camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var tex=new Texture2D(800,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,800,1000),0,0);tex.Apply();File.WriteAllBytes("D:/Unity/AssetIntegration/"+name+"-source.png",tex.EncodeToPNG());RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(obj);UnityEngine.Object.DestroyImmediate(camera.gameObject);UnityEngine.Object.DestroyImmediate(light.gameObject);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}File.WriteAllText("D:/Unity/AssetIntegration/model-probe.txt",log.ToString());}
}}
